                            <div key={i} style={{ padding:'8px 10px', background:'var(--fg-bg3)', borderRadius:8, fontSize:12, color:'var(--fg-text)', marginBottom:6, cursor:'pointer' }} onClick={() => { setInput(p); setShowDebate(false); setDebateResult(null); }}>
                              {p}
                            </div>
